connect.lines:
with refund: http POST https://api.stripe.com/v1/refunds | api=stripe | headers authorization== "Bearer " + {{secrets.STRIPE_TOKEN}} | data=={amount: amount, currency: currency, charge: charge, metadata: {orderId: "#"+orderId}}
with sendmessage: http POST https://api.notification.com/notify | authentication.type=bearer | token={{secrets.NOTIFY_TOKEN}} | data=={to: email, message: "Your refund for order " + orderId + " is on its way"}
with done: plain

