connect.lines:
with pay: service Process payment | mailgun mail.get | url=https://api.mailgun.net/v3/{{domain}}/messages | credentials: username=api, password={{secrets.MAILGUN_API_KEY}}
with send: service Send confirmation email in SendGrid | sendgrid mail — Send Email
with SendGrid: Simple (no dynamic template) | apiKey={{secrets.SENDGRID_API_KEY}} | from.name=Customer | from.email=orders@{{domain}} | to.name={{firstName}} | to.email={{email}} | content.subject=="Order Confirmation" | content.value=="Thank you for your order, {{firstName}}!"

with start: webhook-start | inbound.context=inboundContext | optional: inbound.method=POST | synchronousResponse=true
with stock: http GET {{url}} | authentication.type=bearer | authentication.token={{secrets.TEAMS_TOKEN}}
with teams: teams sendMessageToChannel | authentication.credentials.clientId={{secrets.TEAMS_CLIENT_ID}} | authentication.credentials.tenantId={{secrets.TENANT_ID}} | authentication.credentials.clientSecret={{secrets.TEAMS_CLIENT_SECRET}} | data.sendMessageToChannel.groupId={{teamGroupId}} | data.sendMessageToChannel.channelId={{warehouseChannelId}} | data.sendMessageToChannel.content== "Order checked: " + orderId

